import "server-only";
import { db } from "@/lib/db";

export type CampaignProgressData = {
  id: string;
  createdAt: string;
  observedAt: string;
  finishedAt: string | null;
  queued: number;
  sent: number;
  failed: number;
  cancelled: number;
  review: number;
  pendingDispatch: boolean;
  delays: {
    sendId: string;
    recipient: string;
    state: "READY" | "ATTEMPTING";
    startedAt: string;
  }[];
  outstanding: number;
  sending: number;
  nextSendAt: string | null;
};

// Include observed batches until this History visit ends, even after delivery finishes.
export async function readCampaignProgress(
  user: { id: string; nextSendAt: Date | null },
  campaignIds: string[] = [],
): Promise<CampaignProgressData | null> {
  const campaignSelect = {
    id: true,
    createdAt: true,
    sends: {
      where: { campaign: { userId: user.id }, historyDeletedAt: null },
      select: {
        id: true,
        recipientEmail: true,
        status: true,
        createdAt: true,
        deliveryState: true,
        dispatchedAt: true,
        sentAt: true,
        attemptedAt: true,
        cancelledAt: true,
      },
    },
  } as const;
  const batches = await db.campaign.findMany({
    where: {
      userId: user.id,
      sends: { some: { historyDeletedAt: null } },
      OR: [
        { id: { in: campaignIds } },
        {
          sends: {
            some: {
              OR: [{ status: "QUEUED" }, { deliveryState: "UNCERTAIN" }],
            },
          },
        },
      ],
    },
    select: campaignSelect,
    orderBy: [{ createdAt: "asc" }, { id: "asc" }],
  });
  const now = new Date();
  const [queue, activity] = await Promise.all([
    db.send.findMany({
      where: {
        campaign: { userId: user.id },
        status: "QUEUED",
        deliveryState: { in: ["READY", "ATTEMPTING"] },
      },
      select: {
        id: true,
        recipientEmail: true,
        deliveryState: true,
        createdAt: true,
        attemptedAt: true,
        availableAt: true,
        queueExpiresAt: true,
      },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
    }),
    db.send.aggregate({
      where: { campaign: { userId: user.id }, status: { not: "QUEUED" } },
      _max: { sentAt: true, cancelledAt: true, attemptedAt: true },
    }),
  ]);
  const batchSends = batches.flatMap((batch) => batch.sends);
  const visibleIds = new Set(batchSends.map((send) => send.id));
  const delays: CampaignProgressData["delays"] = [];
  const attempting = queue.filter(
    (send) => send.deliveryState === "ATTEMPTING",
  );
  for (const send of attempting) {
    if (visibleIds.has(send.id) && send.attemptedAt)
      delays.push({
        sendId: send.id,
        recipient: send.recipientEmail,
        state: "ATTEMPTING",
        startedAt: send.attemptedAt.toISOString(),
      });
  }
  // Only the head of the eligible queue accrues pickup delay. Publication
  // timestamps are deliberately excluded: recovery retries must not reset it.
  const next = queue.find(
    (send) =>
      send.deliveryState === "READY" &&
      (!send.availableAt || send.availableAt <= now) &&
      (!send.queueExpiresAt || send.queueExpiresAt > now),
  );
  if (!attempting.length && next && visibleIds.has(next.id)) {
    const start = Math.max(
      +next.createdAt,
      +(next.availableAt ?? next.createdAt),
      +(user.nextSendAt ?? next.createdAt),
      ...Object.values(activity._max).map((date) => +(date ?? next.createdAt)),
    );
    if (start <= +now)
      delays.push({
        sendId: next.id,
        recipient: next.recipientEmail,
        state: "READY",
        startedAt: new Date(start).toISOString(),
      });
  }
  const createdAt = batches[0]?.createdAt;
  const outstanding = batchSends.filter(
    (s) => s.status === "QUEUED" && s.deliveryState !== "UNCERTAIN",
  ).length;
  return createdAt
    ? {
        id: batches.map((batch) => batch.id).join(":"),
        observedAt: now.toISOString(),
        createdAt: createdAt.toISOString(),
        finishedAt: batchSends.every(
          (s) => s.status !== "QUEUED" && s.deliveryState !== "UNCERTAIN",
        )
          ? (batchSends
              .map(
                (s) => s.cancelledAt ?? s.sentAt ?? s.attemptedAt ?? createdAt,
              )
              .sort((a, b) => b.getTime() - a.getTime())[0]
              ?.toISOString() ?? createdAt.toISOString())
          : null,
        queued: outstanding,
        sent: batchSends.filter(
          (s) =>
            ["SENT", "REPLIED"].includes(s.status) &&
            s.deliveryState !== "UNCERTAIN",
        ).length,
        failed: batchSends.filter(
          (s) => s.status === "FAILED" && s.deliveryState !== "UNCERTAIN",
        ).length,
        cancelled: batchSends.filter((s) => s.status === "CANCELLED").length,
        review: batchSends.filter((s) => s.deliveryState === "UNCERTAIN")
          .length,
        pendingDispatch: batchSends.some(
          (s) =>
            s.status === "QUEUED" &&
            !s.dispatchedAt &&
            s.deliveryState !== "UNCERTAIN",
        ),
        delays,
        outstanding,
        sending: batchSends.filter(
          (s) => s.status === "QUEUED" && s.deliveryState === "ATTEMPTING",
        ).length,
        nextSendAt: user.nextSendAt?.toISOString() ?? null,
      }
    : null;
}
